export default function build(w: World): void {
  const base = w.plinth({ footprint: rect(-4, -4, 4, 4), height: 1, project: 1, material: 'stone_bricks' });
  const walls = w.walls({ on: base, height: 4, material: 'oak_planks' });
  w.opening({ in: walls.facade('south'), kind: 'door', width: 1, height: 3 });
  w.opening({ in: walls.facade('east'), kind: 'window', width: 2, height: 1, sill: 1 });
  w.opening({ in: walls.facade('west'), kind: 'window', width: 2, height: 1, sill: 1 });
  w.roof({ on: walls, kind: 'gable', ridge: 'x', pitch: 0.5, material: 'deepslate_tiles' });
}
